INSERT INTO "product" ("id", "producer_id", "status", "name", "country_of_production", "floor_area_m2", "built_up_area_m2", "description", "completion_standard", "production_lead_time_weeks_min", "production_lead_time_weeks_max", "on_site_assembly_days_min", "on_site_assembly_days_max", "house_price_min_cents", "house_price_max_cents", "structural_warranty_years", "category", "rooms", "bedrooms", "bathrooms", "storeys", "external_dimensions", "roof_type", "construction_system", "foundation_options", "customization_scope", "currency", "price_includes", "price_excludes", "featured", "created_at", "updated_at", "deleted_at", "family", "spa_subcategory", "technical_specs", "cover_image_url", "container_subcategory", "installation_warranty_years", "service_scope_description", "transport_dimensions", "crane_requirements", "min_plot_width_m", "room_layout", "faq", "simplified_permit_eligible", "client_requirements", "video_url", "slug", "outdoor_tv_mounting", "outdoor_tv_sun_exposure", "foundation_status") VALUES ('79ac2ca8-124b-56eb-a910-39ec31597473', 'e0030000-0000-4000-8000-000000000103', 'published', 'Wóz 24', 'PL', 24, NULL, 'Całoroczny wóz na stalowym podwoziu z drewnianą zabudową: wnętrze 24 m² oraz zadaszony taras 6 m². Wymiary to 8 m długości plus 2 m tarasu, 3 m szerokości i 3,4 m wysokości. Elewacja jest z modrzewia syberyjskiego, dach z aluminiowej blachy na rąbek stojący, elementy metalowe malowane proszkowo, a wnętrze obite boazerią ze świerku skandynawskiego. W środku są kuchnia z salonem, sypialnia i łazienka. Wóz jest ocieplony, a instalacja elektryczna i hydrauliczna wykonana zgodnie z obowiązującymi normami. Cena jest podana w euro, netto, bez transportu.', 'pod-klucz', 4, 4, NULL, NULL, NULL, NULL, 2, 'mobilny', NULL, 1, 1, 1, NULL, 'Dach łukowy z aluminiowej blachy na rąbek stojący', 'Podwozie: rama ze stali z profili zamkniętych 120x60 mm (ścianka 4 mm). Ściany: drewno konstrukcyjne C24 (kantówka 8x4 cm), elewacja z modrzewia syberyjskiego, membrana wiatroizolacyjna, wełna 8 cm, folia paroprzepuszczalna, wnętrze ze świerku skandynawskiego. Dach: blacha aluminiowa na rąbek stojący, deskowanie, 15 cm wełny mineralnej. Podłoga: boazeria z modrzewia, membrana wiatroizolacyjna, styropian 8 cm, sklejka wodoodporna 18 mm z wykładziną PCV.', NULL, 'Dostępne są dwie wersje kolorystyczne, jak na zdjęciach: naturalny modrzew syberyjski z szarymi elementami albo czerwono-kremowa.', 'EUR', NULL, NULL, false, '2026-10-27T09:56:40.412Z'::timestamptz, '2026-10-27T09:56:40.521Z'::timestamptz, NULL, 'dom', NULL, '{"heatSource":"inne","insulation":"Wełna 8 cm w ścianach, 15 cm wełny mineralnej w dachu, styropian 8 cm w podłodze.","ventilation":"inna","wallBuildUp":"Drewno C24 (kantówka 8x4 cm), elewacja z modrzewia syberyjskiego, wełna 8 cm, wnętrze ze świerku skandynawskiego.","windowClass":"Szyby VSG (z folią, bezpieczne) w oknach i drzwiach.","heatSourceOther":"Brak danych w ofercie producenta.","ventilationOther":"Brak danych w ofercie producenta.","constructionTechnology":"inne","heatTransferCoefficients":"nieznana","constructionTechnologyOther":"Stalowe podwozie z profili zamkniętych 120x60 mm, ściany szkieletowe z drewna C24."}'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '[{"id":"woz-room-0","name":"Kuchnia z salonem, sypialnia i łazienka","areaM2":24,"floorLevel":"parter"}]'::jsonb, NULL, NULL, NULL, NULL, 'woz-24', NULL, NULL, 'temporary') ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('cd7272f9-4d63-4a45-b6e9-28f8586a58a2', '79ac2ca8-124b-56eb-a910-39ec31597473', 'en', 'Wóz 24', 'A year-round wagon on a steel chassis with a timber body: 24 m² inside plus a 6 m² covered terrace. It measures 8 m in length plus a 2 m terrace, 3 m in width and 3.4 m in height. The facade is Siberian larch, the roof is aluminium standing-seam sheet metal, metal parts are powder-coated, and the interior is lined with Scandinavian spruce panelling. Inside are a kitchen with a living area, a bedroom and a bathroom. The wagon is insulated, and the electrical and plumbing installations are made to current standards. The price is given in euro, net, excluding transport.', '2026-10-27T09:56:40.412Z'::timestamptz, '2026-10-27T09:56:40.412Z'::timestamptz, '[{"id":"woz-room-0","name":"Kitchen with living area, bedroom and bathroom"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Chassis: steel frame of 120x60 mm closed profiles (4 mm wall). Walls: C24 structural timber (8x4 cm), Siberian larch facade, wind barrier membrane, 8 cm of wool, vapour-permeable foil, Scandinavian spruce interior. Roof: aluminium standing-seam sheet, boarding, 15 cm of mineral wool. Floor: larch boarding, wind barrier membrane, 8 cm of polystyrene, 18 mm waterproof plywood with PVC covering.', 'Curved roof of aluminium standing-seam sheet metal', 'Two colour versions are available, as in the photos: natural Siberian larch with grey details, or red and cream.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('79f05768-4dfe-4768-846c-f18b6d53f0d0', '79ac2ca8-124b-56eb-a910-39ec31597473', 'de', 'Wóz 24', 'Ein ganzjährig nutzbarer Wagen auf Stahlfahrgestell mit Holzaufbau: 24 m² Innenfläche plus 6 m² überdachte Terrasse. Er misst 8 m in der Länge plus 2 m Terrasse, 3 m in der Breite und 3,4 m in der Höhe. Die Fassade besteht aus sibirischer Lärche, das Dach aus Aluminium-Stehfalzblech, Metallteile sind pulverbeschichtet, und der Innenraum ist mit skandinavischer Fichte verkleidet. Im Inneren befinden sich eine Küche mit Wohnbereich, ein Schlafzimmer und ein Bad. Der Wagen ist gedämmt, Elektro- und Sanitärinstallation sind nach geltenden Normen ausgeführt. Der Preis ist in Euro angegeben, netto, ohne Transport.', '2026-10-27T09:56:40.412Z'::timestamptz, '2026-10-27T09:56:40.412Z'::timestamptz, '[{"id":"woz-room-0","name":"Küche mit Wohnbereich, Schlafzimmer und Bad"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Fahrgestell: Stahlrahmen aus 120x60-mm-Hohlprofilen (4 mm Wandstärke). Wände: Konstruktionsholz C24 (Kantholz 8x4 cm), Fassade aus sibirischer Lärche, Winddichtungsbahn, 8 cm Wolle, diffusionsoffene Folie, Innenraum aus skandinavischer Fichte. Dach: Aluminium-Stehfalzblech, Schalung, 15 cm Mineralwolle. Boden: Lärchenverkleidung, Winddichtungsbahn, 8 cm Polystyrol, 18 mm wasserfestes Sperrholz mit PVC-Belag.', 'Gewölbtes Dach aus Aluminium-Stehfalzblech', 'Es gibt zwei Farbvarianten, wie auf den Fotos: naturbelassene sibirische Lärche mit grauen Elementen oder Rot-Creme.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_translation" ("id", "product_id", "locale", "name", "description", "created_at", "updated_at", "room_layout", "faq", "ai_generated_name", "ai_generated_description", "ai_translated_from_name", "ai_translated_from_description", "client_requirements", "foundation_options", "technical_specs", "construction_system", "roof_type", "customization_scope", "service_scope_description") VALUES ('3a5a1be4-bb2b-453a-8840-9ae91a280147', '79ac2ca8-124b-56eb-a910-39ec31597473', 'nl', 'Wóz 24', 'Een jaarrond bruikbare woonwagen op een stalen onderstel met houten opbouw: 24 m² binnenruimte plus een overdekt terras van 6 m². De afmetingen zijn 8 m lengte plus 2 m terras, 3 m breedte en 3,4 m hoogte. De gevel is van Siberisch lariks, het dak van aluminium liggende felsplaat, metalen onderdelen zijn poedergecoat en het interieur is bekleed met Scandinavisch vurenhout. Binnen zijn een keuken met woonruimte, een slaapkamer en een badkamer. De woonwagen is geïsoleerd en de elektrische en sanitaire installatie is volgens de geldende normen uitgevoerd. De prijs is in euro, netto, exclusief transport.', '2026-10-27T09:56:40.412Z'::timestamptz, '2026-10-27T09:56:40.412Z'::timestamptz, '[{"id":"woz-room-0","name":"Keuken met woonruimte, slaapkamer en badkamer"}]'::jsonb, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'Onderstel: stalen frame van 120x60 mm gesloten profielen (4 mm wanddikte). Wanden: constructiehout C24 (kantelen 8x4 cm), gevel van Siberisch lariks, windscherm, 8 cm wol, dampopen folie, interieur van Scandinavisch vurenhout. Dak: aluminium liggende felsplaat, beplanking, 15 cm minerale wol. Vloer: larikshouten bekleding, windscherm, 8 cm polystyreen, 18 mm waterbestendig multiplex met pvc-vloerbedekking.', 'Gebogen dak van aluminium liggende felsplaat', 'Er zijn twee kleurvarianten, zoals op de foto''s: natuurlijk Siberisch lariks met grijze onderdelen of rood-crème.', NULL) ON CONFLICT DO NOTHING;
INSERT INTO "product_country_eligibility" ("product_id", "country_code", "status", "reason", "created_at", "updated_at") VALUES ('79ac2ca8-124b-56eb-a910-39ec31597473', 'PL', 'conditional', 'Możliwość realizacji i wymagania formalne zależą od konkretnej działki oraz lokalnych ustaleń.', '2026-10-27T09:56:40.412Z'::timestamptz, '2026-10-27T09:56:40.412Z'::timestamptz) ON CONFLICT DO NOTHING;
